// corner), derived from the swept segment-vs-expanded-AABB intersection.
function sweptEntry(ball, prevX, prevY, brick) {
  const r = ball.r;
  const x0 = prevX ?? ball.x;
  const y0 = prevY ?? ball.y;
  const dx = ball.x - x0;
  const dy = ball.y - y0;

  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;

  // Point-in-expanded-box fallback (ball didn't move / no previous position).
