```js
function resolveBounce(ball, hits, entry) {
  let axis = entry.axis;
  if (axis === 'unknown') {
    axis = penetrationAxis(ball, hits);
  }
  const dx = Math.sign(ball.vx);
  const dy = Math.sign(ball.vy);

  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const b of hits) {
    if (b.x < minX) minX = b.x;
    if (b.y < minY) minY = b.y;
    if (b.x + b.w > maxX) maxX = b.x + b.w;
    if (b.y + b.h > maxY) maxY = b.y + b.h;
  }

  if (axis === 'x') {
    ball.vx = -ball.vx;
    ball.x = dx > 0 ? minX - ball.r : maxX + ball.r;
  } else if (axis === 'y') {
    ball.vy = -ball.vy;
    ball.y = dy > 0 ? minY - ball.r : maxY + ball.r;
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = dx > 0 ? minX - ball.r : maxX + ball.r;
    ball.y = dy > 0 ? minY - ball.r : maxY + ball.r;
  }
}
```

