// penetration, per brick, using the brick that is overlapped the deepest.
function penetrationAxis(ball, hits) {
  let best = null;
  for (const b of hits) {
    const penX = Math.min(ball.x + ball.r - b.x, b.x + b.w - (ball.x - ball.r));
    const penY = Math.min(ball.y + ball.r - b.y, b.y + b.h - (ball.y - ball.r));
    const depth = Math.min(penX, penY);
    if (!best || depth < best.depth) {
      best = { axis: penX < penY ? 'x' : penY < penX ? 'y' : 'corner', depth };
    }
  }
