```js
function sweptEntry(ball, prevX, prevY, brick) {
  const r = ball.r;
  const x0 = prevX;
  const y0 = prevY;
  const dx = ball.x - x0;
  const dy = ball.y - y0;

  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;

  // No movement: plain overlap test against the expanded box.
  if (dx === 0 && dy === 0) {
    if (ball.x >= minX && ball.x <= maxX && ball.y >= minY && ball.y <= maxY) {
      return { axis: 'unknown', tEnter: 0 };
    }
    return null;
  }

  let txEnter = -Infinity;
  let txExit = Infinity;
  if (dx > 0) {
    txEnter = (minX - x0) / dx;
    txExit = (maxX - x0) / dx;
  } else if (dx < 0) {
    txEnter = (maxX - x0) / dx;
    txExit = (minX - x0) / dx;
  } else if (x0 < minX || x0 > maxX) {
    return null;
  }

  let tyEnter = -Infinity;
  let tyExit = Infinity;
  if (dy > 0) {
    tyEnter = (minY - y0) / dy;
    tyExit = (maxY - y0) / dy;
  } else if (dy < 0) {
    tyEnter = (maxY - y0) / dy;
    tyExit = (minY - y0) / dy;
  } else if (y0 < minY || y0 > maxY) {
    return null;
  }

  const tEnter = Math.max(txEnter, tyEnter);
  const tExit = Math.min(txExit, tyExit);
  if (tEnter > tExit || tExit < 0 || tEnter > 1) return null;

  if (txEnter === -Infinity && tyEnter === -Infinity) {
    return { axis: 'unknown', tEnter };
  }
  if (txEnter > tyEnter) return { axis: 'x', tEnter };
  if (tyEnter > txEnter) return { axis: 'y', tEnter };
  return { axis: 'corner', tEnter };
}
```

