import { createState, step, brickHit, makeBricks, ballSpeed, WIDTH, HEIGHT } from './game/neon.js';

function simulate(level, seconds) {
  const state = createState(level);
  let destroyed = 0;
  let frames = 0;
  let maxSpeed = 0;
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  const dt = 1 / 60;
  for (let t = 0; t < seconds; t += dt) {
    frames++;
    const lost = step(state, dt);
    const hits = brickHit(state.ball, state.bricks);
    for (const b of hits) { b.alive = false; destroyed++; }
    maxSpeed = Math.max(maxSpeed, Math.hypot(state.ball.vx, state.ball.vy));
    minX = Math.min(minX, state.ball.x); maxX = Math.max(maxX, state.ball.x);
    minY = Math.min(minY, state.ball.y); maxY = Math.max(maxY, state.ball.y);
    if (!Number.isFinite(state.ball.x) || !Number.isFinite(state.ball.y) ||
        !Number.isFinite(state.ball.vx) || !Number.isFinite(state.ball.vy)) {
      throw new Error(`NaN detected at frame ${frames}`);
    }
    if (lost) {
      state.lives -= 1;
      if (state.lives <= 0) break;
      state.ball = createState(state.level).ball;
    }
    if (state.bricks.every((b) => !b.alive)) {
      state.level += 1;
      state.bricks = makeBricks(state.level);
      state.ball = createState(state.level).ball;
    }
  }
  return { frames, destroyed, level: state.level, lives: state.lives, maxSpeed: maxSpeed.toFixed(1),
           xRange: [minX.toFixed(1), maxX.toFixed(1)], yRange: [minY.toFixed(1), maxY.toFixed(1)] };
}

for (const lvl of [1, 3, 6, 10]) {
  const r = simulate(lvl, 30);
  console.log(`level ${lvl} (speed ${ballSpeed(lvl)}):`, JSON.stringify(r));
}
