}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The per-face bounce lives in brickHit() below.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Swept intersection between the ball's path and one brick. The ball is a
// circle, so we test the segment from the previous position to the current
// one against the brick grown by the ball's radius. This catches fast balls
// that would otherwise jump clean over a brick between two frames (tunnelling,
// issue #1): `ballSpeed(6)` × a 50 ms capped frame covers ~35 px against the
// ~34 px needed to cross a brick.
//
// Returns the face the ball entered through, or null when there is no hit:
//   { axis: 'x' }       entered through a side face -> flip vx
//   { axis: 'y' }       entered through the top/bottom -> flip vy
//   { axis: 'corner' }  entered through a corner (equal entry times)
//   { axis: 'unknown' } already inside both slabs at the start: the caller
//                       falls back to the current-overlap penetration
// `tEnter` is the entry time along the segment and is used to pick the brick
// the ball entered most recently when several bricks are hit at once.
function sweptEntry(ball, prevX, prevY, brick) {
  const r = ball.r;
  const x0 = prevX;
  const y0 = prevY;
  const dx = ball.x - x0;
  const dy = ball.y - y0;

  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;

  // No movement (or no previous position): plain point-in-expanded-box test.
  if (dx === 0 && dy === 0) {
    if (ball.x >= minX && ball.x <= maxX && ball.y >= minY && ball.y <= maxY) {
      return { axis: 'unknown', tEnter: 0 };
    }
    return null;
  }

  // Slab method: entry/exit times along the segment for each axis.
  let txEnter = -Infinity;
  let txExit = Infinity;
  if (dx > 0) {
    txEnter = (minX - x0) / dx;
    txExit = (maxX - x0) / dx;
  } else if (dx < 0) {
    txEnter = (maxX - x0) / dx;
    txExit = (minX - x0) / dx;
  } else if (x0 < minX || x0 > maxX) {
    return null;
  }

  let tyEnter = -Infinity;
  let tyExit = Infinity;
  if (dy > 0) {
    tyEnter = (minY - y0) / dy;
    tyExit = (maxY - y0) / dy;
  } else if (dy < 0) {
    tyEnter = (maxY - y0) / dy;
    tyExit = (minY - y0) / dy;
  } else if (y0 < minY || y0 > maxY) {
    return null;
  }

  const tEnter = Math.max(txEnter, tyEnter);
  const tExit = Math.min(txExit, tyExit);
  if (tEnter > tExit || tExit < 0 || tEnter > 1) return null;

  // The axis entered last is the face that was actually hit.
  if (txEnter === -Infinity && tyEnter === -Infinity) {
    return { axis: 'unknown', tEnter };
  }
  if (txEnter > tyEnter) return { axis: 'x', tEnter };
  if (tyEnter > txEnter) return { axis: 'y', tEnter };
  return { axis: 'corner', tEnter };
}

// Fallback face selection: the axis with the smaller penetration, measured on
// the brick that is overlapped the deepest (equal penetrations = corner).
function penetrationAxis(ball, hits) {
  let best = null;
  for (const brick of hits) {
    const penX = Math.min(
      ball.x + ball.r - brick.x,
      brick.x + brick.w - (ball.x - ball.r),
    );
    const penY = Math.min(
      ball.y + ball.r - brick.y,
      brick.y + brick.h - (ball.y - ball.r),
    );
    const depth = Math.min(penX, penY);
    if (!best || depth < best.depth) {
      best = {
        axis: penX < penY ? 'x' : penY < penX ? 'y' : 'corner',
        depth,
      };
    }
  }
  return best.axis;
}

// Applies the bounce against every brick hit in one pass, at most ONCE.
// The grid gap (8 px) is smaller than the ball's diameter (14 px), so the ball
// straddles the seam between two neighbours and overlaps both in the same
// pass: flipping vy twice would cancel out and the ball would go straight
// through. We therefore flip a single component, then push the ball back out
// of the whole block that was hit, so no overlap survives into the next frame
// (sticky bounce).

